CREATE OR REPLACE FUNCTION ramosolo.booking_appointment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE d integer; p integer; old_doctor integer; old_patient integer; pol availability_policies%ROWTYPE;
 now_utc timestamp; local_start timestamp; local_end timestamp; local_date date; session_window record;
 duration integer; matched boolean:=false; closed boolean; has_opening boolean; used integer;
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN RAISE EXCEPTION 'Booking writes require READ COMMITTED isolation'; END IF;
 IF TG_OP IN ('UPDATE','DELETE') THEN old_doctor:=OLD.doctor_id; old_patient:=OLD.patient_id; END IF;
 IF TG_OP='DELETE' THEN d:=OLD.doctor_id; ELSE d:=NEW.doctor_id; END IF;
 FOR d IN SELECT DISTINCT v FROM unnest(ARRAY[d,old_doctor]) AS v WHERE v IS NOT NULL ORDER BY v LOOP
  PERFORM pg_advisory_xact_lock(7001,d);
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 FOR p IN SELECT DISTINCT v FROM unnest(ARRAY[NEW.patient_id,old_patient]) AS v WHERE v IS NOT NULL ORDER BY v LOOP
  PERFORM pg_advisory_xact_lock(7002,p);
 END LOOP;
 -- Identity and institution invariants also apply when releasing capacity.
 IF NEW.patient_id IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM patients WHERE id=NEW.patient_id AND institution_id=NEW.institution_id) THEN
   RAISE EXCEPTION 'Patient belongs to a different institution';
  END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM booking_requests WHERE id=NEW.booking_request_id AND institution_id=NEW.institution_id) THEN
   RAISE EXCEPTION 'Guest request belongs to a different institution';
  END IF;
 END IF;
 IF TG_OP='UPDATE' AND NEW.institution_id<>OLD.institution_id THEN RAISE EXCEPTION 'Appointment ownership cannot change'; END IF;
 IF NEW.status NOT IN ('scheduled','held') THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.status=OLD.status AND
  ROW(NEW.patient_id,NEW.booking_request_id,NEW.doctor_id,NEW.starts_at,NEW.ends_at,NEW.occupied_until,NEW.hold_expires_at,NEW.care_type,NEW.visit_kind)
  IS NOT DISTINCT FROM ROW(OLD.patient_id,OLD.booking_request_id,OLD.doctor_id,OLD.starts_at,OLD.ends_at,OLD.occupied_until,OLD.hold_expires_at,OLD.care_type,OLD.visit_kind) THEN
  RETURN NEW; -- Preserve unchanged legacy appointments without guessing a duration.
 END IF;
 now_utc:=timezone('UTC',clock_timestamp());
 IF TG_OP='UPDATE' AND OLD.status='held' AND (OLD.hold_expires_at IS NULL OR OLD.hold_expires_at<=now_utc) THEN
  RAISE EXCEPTION 'Temporary hold has expired';
 END IF;
 SELECT * INTO pol FROM availability_policies WHERE institution_id=NEW.institution_id AND doctor_id=NEW.doctor_id;
 IF NOT FOUND OR NOT pol.enabled OR NOT pol.holidays_confirmed THEN RAISE EXCEPTION 'Availability is not configured'; END IF;
 IF NOT EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id JOIN institutions i ON i.id=m.institution_id
  WHERE m.user_id=NEW.doctor_id AND m.institution_id=NEW.institution_id AND m.role='dr' AND m.enabled AND u.enabled AND i.kind='medical') THEN
  RAISE EXCEPTION 'Doctor is not enabled in this institution';
 END IF;
 IF NEW.patient_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM patients WHERE id=NEW.patient_id AND doctor_id=NEW.doctor_id) THEN
  RAISE EXCEPTION 'Patient is not assigned to this doctor';
 END IF;
 IF NEW.care_type IS NULL OR NEW.care_type NOT IN ('inpatient','outpatient') OR NEW.visit_kind IS NULL OR NEW.visit_kind NOT IN ('routine','first','assessment')
  OR NEW.ends_at IS NULL OR NEW.occupied_until IS NULL THEN RAISE EXCEPTION 'Complete typed appointment interval is required'; END IF;
 IF NEW.status='held' AND (NEW.booking_request_id IS NULL OR NEW.hold_expires_at IS NULL
  OR NEW.hold_expires_at<=now_utc OR NEW.hold_expires_at>now_utc+make_interval(mins=>pol.hold_minutes)) THEN
  RAISE EXCEPTION 'Invalid temporary hold expiry';
 END IF;
 local_start:=NEW.starts_at AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Johannesburg';
 local_end:=NEW.occupied_until AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Johannesburg';
 local_date:=local_start::date;
 IF NEW.starts_at<=now_utc OR local_date>(now_utc AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Johannesburg')::date+pol.horizon_days THEN
  RAISE EXCEPTION 'Appointment is outside the future booking window';
 END IF;
 closed:=extract(isodow FROM local_date)::integer IN (4,6,7)
  OR EXISTS(SELECT 1 FROM public_holidays WHERE institution_id=NEW.institution_id AND day=local_date)
  OR EXISTS(SELECT 1 FROM availability_exceptions WHERE policy_id=pol.id AND day=local_date AND kind IN ('leave','closure'));
 has_opening:=EXISTS(SELECT 1 FROM availability_exceptions WHERE policy_id=pol.id AND day=local_date AND kind='opening');
 FOR session_window IN
  SELECT e.opens_at,e.closes_at,e.duration_minutes,e.first_minutes,e.assessment_minutes,e.break_minutes,e.care_type
   FROM availability_exceptions e WHERE e.policy_id=pol.id AND e.day=local_date AND e.kind='opening' AND (NOT closed OR e.override_closure)
  UNION ALL
  SELECT s.opens_at,s.closes_at,s.duration_minutes,s.first_minutes,s.assessment_minutes,s.break_minutes,s.care_type
   FROM availability_sessions s WHERE s.policy_id=pol.id AND s.weekday=extract(isodow FROM local_date)::integer-1 AND NOT has_opening AND NOT closed
 LOOP
  duration:=CASE NEW.visit_kind WHEN 'routine' THEN session_window.duration_minutes WHEN 'first' THEN session_window.first_minutes ELSE session_window.assessment_minutes END;
  IF session_window.care_type=NEW.care_type AND local_start>=local_date+session_window.opens_at AND local_end<=local_date+session_window.closes_at
   AND NEW.ends_at=NEW.starts_at+make_interval(mins=>duration)
   AND NEW.occupied_until=NEW.ends_at+make_interval(mins=>session_window.break_minutes)
   AND mod(extract(epoch FROM (local_start-(local_date+session_window.opens_at))),((duration+session_window.break_minutes)*60)::numeric)=0 THEN
   matched:=true; EXIT;
  END IF;
 END LOOP;
 IF NOT matched THEN RAISE EXCEPTION 'Appointment is outside configured sessions or breaks'; END IF;
 IF EXISTS(SELECT 1 FROM calendar_blocks b WHERE b.doctor_id=NEW.doctor_id AND b.enabled AND b.starts_at<NEW.occupied_until AND NEW.starts_at<b.ends_at) THEN RAISE EXCEPTION 'Appointment overlaps blocked time'; END IF;
 SELECT count(*) INTO used FROM appointments a WHERE a.id<>COALESCE(NEW.id,-1) AND a.doctor_id=NEW.doctor_id
  AND a.institution_id=NEW.institution_id AND (a.starts_at AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Johannesburg')::date=local_date
  AND (a.status='scheduled' OR (a.status='held' AND a.hold_expires_at>now_utc));
 IF used>=pol.daily_limit THEN RAISE EXCEPTION 'Daily appointment limit reached'; END IF;
 IF EXISTS(SELECT 1 FROM appointments a WHERE a.id<>COALESCE(NEW.id,-1)
  AND (a.doctor_id=NEW.doctor_id OR (NEW.patient_id IS NOT NULL AND a.patient_id=NEW.patient_id))
  AND (a.status='scheduled' OR (a.status='held' AND a.hold_expires_at>now_utc))
  AND ((a.occupied_until IS NULL AND (a.starts_at AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Johannesburg')::date=local_date)
   OR (a.starts_at<NEW.occupied_until AND NEW.starts_at<a.occupied_until))) THEN RAISE EXCEPTION 'Appointment intervals overlap'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.booking_config_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE d integer; inst integer; policy integer; row_id integer;
BEGIN
 IF current_setting('transaction_isolation') <> 'read committed' THEN
  RAISE EXCEPTION 'Booking writes require READ COMMITTED isolation';
 END IF;
 IF TG_TABLE_NAME='public_holidays' THEN
  IF TG_OP='DELETE' THEN inst:=OLD.institution_id; ELSE inst:=NEW.institution_id; END IF;
  IF TG_OP='UPDATE' AND NEW.institution_id<>OLD.institution_id THEN RAISE EXCEPTION 'Holiday ownership cannot change'; END IF;
  FOR d IN SELECT doctor_id FROM availability_policies WHERE institution_id=inst ORDER BY doctor_id LOOP
   PERFORM pg_advisory_xact_lock(7001,d);
  END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
 ELSIF TG_TABLE_NAME='availability_policies' THEN
  IF TG_OP='DELETE' THEN d:=OLD.doctor_id; inst:=OLD.institution_id;
  ELSE d:=NEW.doctor_id; inst:=NEW.institution_id; END IF;
  IF TG_OP='UPDATE' AND (NEW.doctor_id<>OLD.doctor_id OR NEW.institution_id<>OLD.institution_id) THEN
   RAISE EXCEPTION 'Policy ownership cannot change';
  END IF;
 ELSE
  IF TG_OP='DELETE' THEN policy:=OLD.policy_id; ELSE policy:=NEW.policy_id; END IF;
  IF TG_OP='UPDATE' AND NEW.policy_id<>OLD.policy_id THEN RAISE EXCEPTION 'Session ownership cannot change'; END IF;
  SELECT doctor_id,institution_id INTO d,inst FROM availability_policies WHERE id=policy;
 END IF;
 IF d IS NULL THEN RAISE EXCEPTION 'Unknown scheduling policy'; END IF;
 PERFORM pg_advisory_xact_lock(7001,d);
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 IF NOT EXISTS (SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id JOIN institutions i ON i.id=m.institution_id
  WHERE m.user_id=d AND m.institution_id=inst AND m.role='dr' AND m.enabled AND u.enabled AND i.kind='medical') THEN
  RAISE EXCEPTION 'Doctor must have an enabled medical institution membership';
 END IF;
 IF TG_TABLE_NAME IN ('availability_sessions','availability_exceptions') THEN
  IF extract(second FROM NEW.opens_at)<>0 OR extract(second FROM NEW.closes_at)<>0 THEN
   RAISE EXCEPTION 'Session hours require whole minutes';
  END IF;
 END IF;
 IF TG_TABLE_NAME='availability_sessions' THEN
  IF EXISTS (SELECT 1 FROM availability_sessions s WHERE s.policy_id=NEW.policy_id
   AND s.weekday=NEW.weekday AND s.id<>COALESCE(NEW.id,-1) AND s.opens_at<NEW.closes_at AND NEW.opens_at<s.closes_at) THEN
   RAISE EXCEPTION 'Weekly sessions overlap';
  END IF;
 ELSIF TG_TABLE_NAME='availability_exceptions' THEN
  IF NOT EXISTS (SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.user_id=NEW.approved_by
   AND m.institution_id=inst AND m.enabled AND u.enabled AND (m.role='admin' OR (m.role='dr' AND m.user_id=d))) THEN
   RAISE EXCEPTION 'Exception requires authorized staff approval';
  END IF;
  IF length(trim(NEW.reason))<3 OR NEW.approved_at IS NULL THEN RAISE EXCEPTION 'Approval reason is required'; END IF;
  IF NEW.kind='opening' AND EXISTS (SELECT 1 FROM availability_exceptions e WHERE e.policy_id=NEW.policy_id
   AND e.day=NEW.day AND e.kind='opening' AND e.id<>COALESCE(NEW.id,-1)
   AND e.opens_at<NEW.closes_at AND NEW.opens_at<e.closes_at) THEN
   RAISE EXCEPTION 'Dated sessions overlap';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.calendar_appointment_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
BEGIN
 IF NEW.calendar_uid !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'Invalid calendar reference'; END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.calendar_uid<>OLD.calendar_uid OR ROW(NEW.institution_id,NEW.doctor_id,NEW.patient_id,NEW.booking_request_id)
    IS DISTINCT FROM ROW(OLD.institution_id,OLD.doctor_id,OLD.patient_id,OLD.booking_request_id) THEN
   RAISE EXCEPTION 'Appointment identity and calendar reference are immutable';
  END IF;
  NEW.was_confirmed:=CASE WHEN OLD.was_confirmed IS TRUE OR OLD.status IN ('scheduled','completed','no_show')
    OR NEW.status IN ('scheduled','completed','no_show') THEN true ELSE OLD.was_confirmed END;
  NEW.schedule_version:=OLD.schedule_version+CASE WHEN ROW(NEW.starts_at,NEW.ends_at,NEW.occupied_until,NEW.status,NEW.care_type,NEW.visit_kind,NEW.hold_expires_at)
    IS DISTINCT FROM ROW(OLD.starts_at,OLD.ends_at,OLD.occupied_until,OLD.status,OLD.care_type,OLD.visit_kind,OLD.hold_expires_at) THEN 1 ELSE 0 END;
 ELSE
  NEW.was_confirmed:=NEW.status IN ('scheduled','completed','no_show');
  NEW.schedule_version:=1;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.calendar_block_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE actor integer; now_utc timestamp;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Calendar writes require READ COMMITTED isolation'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Release calendar blocks instead of deleting their history'; END IF;
 PERFORM pg_advisory_xact_lock(7001,NEW.doctor_id);
 actor:=NEW.created_by;
 IF TG_OP='UPDATE' THEN
  IF NOT OLD.enabled THEN RAISE EXCEPTION 'Released block history is immutable'; END IF;
  IF ROW(NEW.institution_id,NEW.doctor_id,NEW.starts_at,NEW.ends_at,NEW.reason,NEW.created_by,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.institution_id,OLD.doctor_id,OLD.starts_at,OLD.ends_at,OLD.reason,OLD.created_by,OLD.created_at)
    OR (NOT OLD.enabled AND NEW.enabled) THEN RAISE EXCEPTION 'Calendar block history is immutable'; END IF;
  actor:=NEW.released_by;
  IF NEW.enabled OR NEW.released_by IS NULL OR NEW.released_at IS NULL THEN RAISE EXCEPTION 'Release approval is required'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id JOIN institutions i ON i.id=m.institution_id
  WHERE m.institution_id=NEW.institution_id AND m.user_id=actor AND m.enabled AND u.enabled AND i.kind='medical'
   AND (m.role='admin' OR (m.role='dr' AND m.user_id=NEW.doctor_id))) THEN RAISE EXCEPTION 'Calendar block requires authorized staff'; END IF;
 IF TG_OP='UPDATE' THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.institution_id=NEW.institution_id
   AND m.user_id=NEW.doctor_id AND m.role='dr' AND m.enabled AND u.enabled) THEN RAISE EXCEPTION 'Doctor is not enabled'; END IF;
 now_utc:=timezone('UTC',clock_timestamp());
 IF NEW.starts_at<=now_utc OR NEW.ends_at<=NEW.starts_at THEN RAISE EXCEPTION 'Choose a future calendar block'; END IF;
 IF EXISTS(SELECT 1 FROM calendar_blocks b WHERE b.doctor_id=NEW.doctor_id AND b.enabled AND b.starts_at<NEW.ends_at AND NEW.starts_at<b.ends_at) THEN
  RAISE EXCEPTION 'Calendar blocks overlap'; END IF;
 IF EXISTS(SELECT 1 FROM appointments a WHERE a.doctor_id=NEW.doctor_id
   AND (a.status='scheduled' OR (a.status='held' AND a.hold_expires_at>now_utc))
   AND ((a.occupied_until IS NOT NULL AND a.starts_at<NEW.ends_at AND NEW.starts_at<a.occupied_until)
    OR (a.occupied_until IS NULL AND
     (((a.starts_at AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Johannesburg')::date::timestamp AT TIME ZONE 'Africa/Johannesburg') AT TIME ZONE 'UTC')<NEW.ends_at
     AND NEW.starts_at<((((a.starts_at AT TIME ZONE 'UTC' AT TIME ZONE 'Africa/Johannesburg')::date+1)::timestamp AT TIME ZONE 'Africa/Johannesburg') AT TIME ZONE 'UTC')))) THEN
  RAISE EXCEPTION 'Calendar block overlaps an active appointment'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.financial_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE actor integer; action_name text; resource text;
BEGIN
 IF TG_TABLE_NAME='medical_invoices' THEN
  actor:=CASE WHEN TG_OP='INSERT' THEN NEW.created_by ELSE NEW.voided_by END;
  action_name:=CASE WHEN TG_OP='INSERT' THEN 'issue_invoice' ELSE 'void_invoice' END;resource:='invoice';
 ELSE actor:=NEW.actor_id;action_name:='manual_'||NEW.kind;resource:='payment_entry';END IF;
 INSERT INTO audit_events(institution_id,actor_id,action,resource_type,resource_id,created_at)
 VALUES(NEW.institution_id,actor,action_name,resource,NEW.id,timezone('UTC',clock_timestamp()));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.followup_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE ap appointments; alert attendance_followups; actor integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Administrative history cannot be deleted'; END IF;
 IF TG_TABLE_NAME='followup_policies' THEN
  IF NOT followup_actor_allowed(NEW.institution_id,NULL,NEW.updated_by,true) THEN RAISE EXCEPTION 'Follow-up policy requires institution administrator'; END IF;
  IF TG_OP='UPDATE' AND (NEW.institution_id<>OLD.institution_id OR NEW.version<>OLD.version+1) THEN RAISE EXCEPTION 'Policy updates require a new version'; END IF;
  RETURN NEW;
 END IF;
 IF TG_TABLE_NAME='attendance_followup_reviews' THEN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Review history is append-only'; END IF;
  SELECT * INTO alert FROM attendance_followups WHERE id=NEW.followup_id;
  SELECT * INTO ap FROM appointments WHERE id=alert.appointment_id;
  IF alert.institution_id IS DISTINCT FROM NEW.institution_id OR NOT followup_actor_allowed(NEW.institution_id,ap.doctor_id,NEW.actor_id)
    OR alert.state<>NEW.action THEN RAISE EXCEPTION 'Review must match an authorized scoped alert action'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO ap FROM appointments WHERE id=NEW.appointment_id;
 IF ap.id IS NULL OR ap.institution_id<>NEW.institution_id THEN RAISE EXCEPTION 'Administrative record institution mismatch'; END IF;
 IF TG_TABLE_NAME='appointment_attendance_events' THEN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Attendance event history is append-only'; END IF;
  IF NEW.actor_id IS NOT NULL AND NOT followup_actor_allowed(NEW.institution_id,ap.doctor_id,NEW.actor_id) THEN RAISE EXCEPTION 'Unauthorized event actor'; END IF;
 ELSIF TG_TABLE_NAME='appointment_confirmation_requests' THEN
  IF ap.schedule_version<>NEW.appointment_version OR ap.starts_at<>NEW.scheduled_start OR ap.status<>'scheduled'
    OR ap.starts_at<=timezone('UTC',clock_timestamp()) THEN RAISE EXCEPTION 'Confirmation requires current upcoming appointment'; END IF;
  actor=CASE WHEN TG_OP='INSERT' THEN NEW.requested_by ELSE NEW.confirmed_by END;
  IF NOT followup_actor_allowed(NEW.institution_id,ap.doctor_id,actor) THEN RAISE EXCEPTION 'Unauthorized confirmation actor'; END IF;
  IF TG_OP='UPDATE' AND (ROW(NEW.institution_id,NEW.appointment_id,NEW.appointment_version,NEW.scheduled_start,NEW.deadline,NEW.requested_at,NEW.requested_by,NEW.policy_version)
    IS DISTINCT FROM ROW(OLD.institution_id,OLD.appointment_id,OLD.appointment_version,OLD.scheduled_start,OLD.deadline,OLD.requested_at,OLD.requested_by,OLD.policy_version)
    OR OLD.confirmed_at IS NOT NULL OR NEW.confirmed_at IS NULL) THEN RAISE EXCEPTION 'Confirmation requests are immutable except for first response'; END IF;
 ELSIF TG_TABLE_NAME='attendance_followups' THEN
  IF TG_OP='INSERT' AND (NEW.appointment_version<>ap.schedule_version OR NOT EXISTS(SELECT 1 FROM followup_policies p WHERE p.institution_id=NEW.institution_id AND p.version=NEW.policy_version AND p.enabled)) THEN RAISE EXCEPTION 'Follow-up generation mismatch'; END IF;
  IF TG_OP='UPDATE' AND ROW(NEW.institution_id,NEW.appointment_id,NEW.appointment_version,NEW.rule,NEW.policy_version,NEW.rule_version,NEW.reason,NEW.suggested_action,NEW.evidence::text,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.institution_id,OLD.appointment_id,OLD.appointment_version,OLD.rule,OLD.policy_version,OLD.rule_version,OLD.reason,OLD.suggested_action,OLD.evidence::text,OLD.created_at) THEN RAISE EXCEPTION 'Follow-up evidence snapshots are immutable'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.medical_assignment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE inst integer; doctor integer;
BEGIN
 IF TG_TABLE_NAME='memberships' THEN
  IF NEW.role='dr_assist' AND NOT EXISTS (
   SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id
   WHERE m.user_id=NEW.supervising_doctor_id AND m.institution_id=NEW.institution_id
    AND m.role='dr' AND m.enabled AND u.enabled
  ) THEN RAISE EXCEPTION 'Assistant requires an enabled doctor in the same institution'; END IF;
 ELSIF TG_TABLE_NAME='patients' THEN
  IF NOT EXISTS (SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id
   JOIN institutions i ON i.id=m.institution_id WHERE m.user_id=NEW.doctor_id
    AND m.institution_id=NEW.institution_id AND m.role='dr' AND m.enabled AND u.enabled AND i.kind='medical')
  THEN RAISE EXCEPTION 'Patient requires an enabled doctor in the same medical institution'; END IF;
  IF NEW.user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM memberships m
   WHERE m.user_id=NEW.user_id AND m.institution_id=NEW.institution_id AND m.role='patient')
  THEN RAISE EXCEPTION 'Patient account requires a patient membership in the same institution'; END IF;
 ELSIF TG_TABLE_NAME='care_assignments' THEN
  SELECT institution_id INTO inst FROM patients WHERE id=NEW.patient_id;
  IF NOT EXISTS (SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id
   WHERE m.user_id=NEW.nurse_id AND m.institution_id=inst AND m.role='nurse' AND m.enabled AND u.enabled)
  THEN RAISE EXCEPTION 'Nurse requires membership in the patient institution'; END IF;
 ELSIF TG_TABLE_NAME='appointments' AND NEW.patient_id IS NOT NULL THEN
  IF NOT EXISTS (SELECT 1 FROM patients p WHERE p.id=NEW.patient_id
   AND p.institution_id=NEW.institution_id AND p.doctor_id=NEW.doctor_id)
  THEN RAISE EXCEPTION 'Appointment requires the assigned patient doctor and institution'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.medical_invoice_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE appt appointments%ROWTYPE; net numeric; actor integer;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Financial writes require READ COMMITTED isolation'; END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Invoice history cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  SELECT * INTO appt FROM appointments WHERE id=NEW.appointment_id FOR UPDATE;
  IF NOT FOUND OR appt.institution_id<>NEW.institution_id OR appt.doctor_id<>NEW.doctor_id OR appt.was_confirmed IS NOT TRUE THEN
   RAISE EXCEPTION 'Invoice needs a confirmed appointment with matching ownership'; END IF;
  IF NEW.state<>'issued' OR NEW.voided_by IS NOT NULL OR NEW.voided_at IS NOT NULL THEN RAISE EXCEPTION 'New invoices must be issued'; END IF;
  IF NEW.total::text='NaN' OR NEW.total<=0 OR NEW.currency<>'ZAR' THEN RAISE EXCEPTION 'Invoice requires a positive ZAR total'; END IF;
  actor:=NEW.created_by;
  NEW.created_at:=timezone('UTC',clock_timestamp());
 ELSE
  IF ROW(NEW.institution_id,NEW.doctor_id,NEW.appointment_id,NEW.total,NEW.currency,NEW.created_by,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.institution_id,OLD.doctor_id,OLD.appointment_id,OLD.total,OLD.currency,OLD.created_by,OLD.created_at)
    OR OLD.state='void' OR NEW.state<>'void' OR NEW.voided_by IS NULL OR NEW.voided_at IS NULL THEN RAISE EXCEPTION 'Invoice values and history are immutable'; END IF;
  SELECT coalesce(sum(CASE WHEN kind='receipt' THEN amount ELSE -amount END),0) INTO net FROM medical_payment_entries WHERE invoice_id=OLD.id;
  IF net<>0 THEN RAISE EXCEPTION 'Refund received funds before voiding'; END IF;
  actor:=NEW.voided_by;NEW.voided_at:=timezone('UTC',clock_timestamp());
 END IF;
 IF NOT EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id JOIN institutions i ON i.id=m.institution_id
  WHERE m.institution_id=NEW.institution_id AND m.user_id=actor AND m.enabled AND u.enabled AND i.kind='medical'
   AND (m.role='admin' OR (TG_OP='INSERT' AND m.role='dr' AND m.user_id=NEW.doctor_id))) THEN RAISE EXCEPTION 'Invoice action requires authorized staff'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.medical_payment_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE inv medical_invoices%ROWTYPE; original medical_payment_entries%ROWTYPE; net numeric; refunded numeric;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Payment entries are append-only; record a linked refund to correct them'; END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Financial writes require READ COMMITTED isolation'; END IF;
 SELECT * INTO inv FROM medical_invoices WHERE id=NEW.invoice_id FOR UPDATE;
 IF NOT FOUND OR inv.institution_id<>NEW.institution_id OR inv.state<>'issued' THEN RAISE EXCEPTION 'Invoice ownership or state is invalid'; END IF;
 IF NOT EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.institution_id=inv.institution_id
  AND m.user_id=NEW.actor_id AND m.enabled AND u.enabled AND (m.role='admin' OR (NEW.kind='receipt' AND m.role='dr' AND m.user_id=inv.doctor_id))) THEN
  RAISE EXCEPTION 'Money movement requires authorized staff'; END IF;
 IF NEW.amount::text='NaN' OR NEW.amount<=0 OR NEW.effective_at>timezone('UTC',clock_timestamp()) OR length(NEW.submission_key)<>64 OR length(NEW.submission_fingerprint)<>64 THEN
  RAISE EXCEPTION 'Invalid money movement'; END IF;
 SELECT coalesce(sum(CASE WHEN kind='receipt' THEN amount ELSE -amount END),0) INTO net FROM medical_payment_entries WHERE invoice_id=inv.id;
 IF NEW.kind='receipt' THEN
  IF NEW.amount>inv.total-net THEN RAISE EXCEPTION 'Receipt exceeds outstanding balance'; END IF;
 ELSE
  SELECT * INTO original FROM medical_payment_entries WHERE id=NEW.original_receipt_id AND invoice_id=inv.id AND kind='receipt';
  IF NOT FOUND OR NEW.method<>original.method OR NEW.effective_at<original.effective_at THEN RAISE EXCEPTION 'Refund requires its original receipt'; END IF;
  SELECT coalesce(sum(amount),0) INTO refunded FROM medical_payment_entries WHERE original_receipt_id=original.id AND kind='refund';
  IF NEW.amount>original.amount-refunded OR NEW.amount>net THEN RAISE EXCEPTION 'Refund exceeds unrefunded receipts'; END IF;
 END IF;
 NEW.recorded_at:=timezone('UTC',clock_timestamp());
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.notification_outbox_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE doctor integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Reminder job history cannot be deleted'; END IF;
 IF TG_OP='INSERT' THEN
  PERFORM pg_advisory_xact_lock(7010,NEW.institution_id);
  SELECT doctor_id INTO doctor FROM appointments WHERE id=NEW.appointment_id AND institution_id=NEW.institution_id;
  IF doctor IS NULL THEN RAISE EXCEPTION 'Unknown scoped appointment'; END IF;
  PERFORM pg_advisory_xact_lock(7001,doctor);
  IF NOT reminder_job_current(NEW) OR NEW.state<>'pending' OR NEW.attempt_count<>0 OR NEW.sent_at IS NOT NULL OR NEW.invalidated_at IS NOT NULL THEN
   RAISE EXCEPTION 'Reminder jobs require current appointment, policy and recipient consent'; END IF;
 ELSE
  IF ROW(NEW.public_id,NEW.institution_id,NEW.appointment_id,NEW.appointment_version,NEW.scheduled_start,NEW.preference_id,
    NEW.preference_version,NEW.recipient_user_id,NEW.consent_at,NEW.policy_id,NEW.policy_version,NEW.lead_minutes,NEW.channel,NEW.due_at,NEW.max_attempts,NEW.created_at)
   IS DISTINCT FROM ROW(OLD.public_id,OLD.institution_id,OLD.appointment_id,OLD.appointment_version,OLD.scheduled_start,OLD.preference_id,
    OLD.preference_version,OLD.recipient_user_id,OLD.consent_at,OLD.policy_id,OLD.policy_version,OLD.lead_minutes,OLD.channel,OLD.due_at,OLD.max_attempts,OLD.created_at) THEN
    RAISE EXCEPTION 'Reminder job snapshots are immutable'; END IF;
  IF OLD.state<>'pending' AND (NEW.state<>OLD.state OR NEW.attempt_count<>OLD.attempt_count OR NEW.sent_at IS DISTINCT FROM OLD.sent_at OR NEW.result_code IS DISTINCT FROM OLD.result_code) THEN
   RAISE EXCEPTION 'Terminal delivery history is immutable'; END IF;
  IF NEW.attempt_count<OLD.attempt_count OR NEW.attempt_count>OLD.attempt_count+1 THEN RAISE EXCEPTION 'Invalid reminder attempt count'; END IF;
  IF OLD.state='pending' AND NEW.state='sent' THEN
   IF NOT reminder_job_current(NEW) OR NEW.invalidated_at IS NOT NULL OR NEW.attempt_count<1 OR NEW.due_at>timezone('UTC',clock_timestamp())
    OR NOT EXISTS(SELECT 1 FROM in_app_notifications WHERE job_id=NEW.id AND institution_id=NEW.institution_id) THEN
    RAISE EXCEPTION 'A sent state requires actual in-app publication with current consent'; END IF;
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.reminder_configuration_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE inst integer; owner integer; pol reminder_policies%ROWTYPE; patient patients%ROWTYPE; guest booking_requests%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'Reminder writes require READ COMMITTED isolation'; END IF;
 IF TG_TABLE_NAME='reminder_leads' THEN
  IF TG_OP='DELETE' THEN SELECT * INTO pol FROM reminder_policies WHERE id=OLD.policy_id;
  ELSE SELECT * INTO pol FROM reminder_policies WHERE id=NEW.policy_id; END IF;
  inst:=pol.institution_id;
 ELSE
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Disable reminder configuration instead of deleting its history'; END IF;
  inst:=NEW.institution_id;
 END IF;
 PERFORM pg_advisory_xact_lock(7010,inst);
 IF NOT EXISTS(SELECT 1 FROM institutions WHERE id=inst AND kind='medical') THEN RAISE EXCEPTION 'Medical institution required'; END IF;
 IF TG_TABLE_NAME='reminder_policies' THEN
  IF NOT EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.user_id=NEW.updated_by
   AND m.institution_id=inst AND m.role='admin' AND m.enabled AND u.enabled) THEN RAISE EXCEPTION 'Reminder configuration requires institution administrator'; END IF;
  IF TG_OP='UPDATE' THEN
   IF NEW.institution_id<>OLD.institution_id THEN RAISE EXCEPTION 'Reminder policy ownership is immutable'; END IF;
   NEW.version:=OLD.version+1;
  ELSE NEW.version:=1;END IF;
  NEW.updated_at:=timezone('UTC',clock_timestamp());
 ELSIF TG_TABLE_NAME='reminder_leads' THEN
  IF TG_OP='UPDATE' AND NEW.policy_id<>OLD.policy_id THEN RAISE EXCEPTION 'Reminder lead ownership is immutable'; END IF;
  -- Updating the policy serializes configuration and invalidates the old generation.
  UPDATE reminder_policies SET version=version+1 WHERE id=pol.id;
 ELSE
  IF TG_OP='UPDATE' THEN
   IF ROW(NEW.institution_id,NEW.patient_id,NEW.booking_request_id) IS DISTINCT FROM ROW(OLD.institution_id,OLD.patient_id,OLD.booking_request_id) THEN
    RAISE EXCEPTION 'Communication preference ownership is immutable'; END IF;
   NEW.version:=OLD.version+1;
  ELSE NEW.version:=1;END IF;
  IF NEW.email_enabled OR NEW.sms_enabled THEN RAISE EXCEPTION 'External reminder delivery is disabled'; END IF;
  IF NEW.patient_id IS NOT NULL THEN
   SELECT * INTO patient FROM patients WHERE id=NEW.patient_id AND institution_id=inst;
   IF NOT FOUND OR patient.user_id IS NULL OR NEW.changed_by IS DISTINCT FROM patient.user_id OR NEW.guest_verified_digest IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.user_id=patient.user_id
     AND m.institution_id=inst AND m.role='patient' AND m.enabled AND u.enabled) THEN RAISE EXCEPTION 'Patient must set their own preferences'; END IF;
  ELSE
   SELECT * INTO guest FROM booking_requests WHERE id=NEW.booking_request_id AND institution_id=inst;
   IF NOT FOUND OR NEW.changed_by IS NOT NULL THEN RAISE EXCEPTION 'Invalid verified booking preference'; END IF;
   IF NEW.in_app_enabled AND (guest.token_expires_at<=timezone('UTC',clock_timestamp()) OR NEW.guest_verified_digest IS DISTINCT FROM guest.token_digest
    OR NOT EXISTS(SELECT 1 FROM appointments WHERE booking_request_id=guest.id AND institution_id=inst AND status='scheduled'
     AND starts_at>timezone('UTC',clock_timestamp()))) THEN RAISE EXCEPTION 'Verified future booking required'; END IF;
  END IF;
  IF NEW.in_app_enabled AND (NEW.in_app_consent_at IS NULL OR NEW.in_app_consent_at>timezone('UTC',clock_timestamp())) THEN RAISE EXCEPTION 'Explicit reminder consent is required'; END IF;
  NEW.changed_at:=timezone('UTC',clock_timestamp());
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.reminder_delivery_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE job notification_outbox%ROWTYPE; pol reminder_policies%ROWTYPE;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Delivery and attempt history is append-only'; END IF;
 SELECT * INTO job FROM notification_outbox WHERE id=NEW.job_id AND institution_id=NEW.institution_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Invalid scoped reminder job'; END IF;
 IF TG_TABLE_NAME='in_app_notifications' THEN
  SELECT * INTO pol FROM reminder_policies WHERE id=job.policy_id;
  IF NOT reminder_job_current(job) OR job.state<>'pending' OR job.attempt_count<1 OR job.due_at>timezone('UTC',clock_timestamp())
   OR NEW.expires_at<=timezone('UTC',clock_timestamp()) OR NEW.expires_at>job.scheduled_start
   OR NEW.expires_at>timezone('UTC',clock_timestamp())+make_interval(mins=>pol.link_minutes) THEN
    RAISE EXCEPTION 'In-app publication is not currently eligible'; END IF;
 ELSE
  IF NEW.number<1 OR NEW.number<>job.attempt_count OR (NEW.outcome='sent' AND job.state<>'sent')
   OR (NEW.outcome='transient_failure' AND job.state NOT IN ('pending','failed'))
   OR (NEW.outcome='permanent_failure' AND job.state<>'failed') THEN RAISE EXCEPTION 'Attempt result does not match delivery state'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION ramosolo.reminder_job_current(j ramosolo.notification_outbox)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
DECLARE appt appointments%ROWTYPE; pref communication_preferences%ROWTYPE; pol reminder_policies%ROWTYPE;
BEGIN
 SELECT * INTO appt FROM appointments WHERE id=j.appointment_id AND institution_id=j.institution_id;
 IF NOT FOUND OR appt.status<>'scheduled' OR appt.starts_at<=timezone('UTC',clock_timestamp()) OR appt.schedule_version<>j.appointment_version
  OR appt.starts_at<>j.scheduled_start THEN RETURN false; END IF;
 SELECT * INTO pref FROM communication_preferences WHERE id=j.preference_id AND institution_id=j.institution_id;
 IF NOT FOUND OR NOT pref.in_app_enabled OR pref.in_app_consent_at IS NULL OR pref.version<>j.preference_version OR pref.in_app_consent_at<>j.consent_at
  OR pref.patient_id IS DISTINCT FROM appt.patient_id OR pref.booking_request_id IS DISTINCT FROM appt.booking_request_id THEN RETURN false; END IF;
 IF pref.patient_id IS NOT NULL THEN
  IF pref.changed_by IS DISTINCT FROM j.recipient_user_id OR NOT EXISTS(SELECT 1 FROM patients p JOIN users u ON u.id=p.user_id
   JOIN memberships m ON m.user_id=u.id AND m.institution_id=p.institution_id WHERE p.id=pref.patient_id
    AND p.institution_id=j.institution_id AND p.user_id=j.recipient_user_id AND m.role='patient' AND m.enabled AND u.enabled) THEN RETURN false; END IF;
 ELSE
  IF j.recipient_user_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM booking_requests WHERE id=pref.booking_request_id AND institution_id=j.institution_id
   AND token_digest=pref.guest_verified_digest AND token_expires_at>timezone('UTC',clock_timestamp())) THEN RETURN false; END IF;
 END IF;
 SELECT * INTO pol FROM reminder_policies WHERE id=j.policy_id AND institution_id=j.institution_id;
 IF NOT FOUND OR NOT pol.enabled OR pol.version<>j.policy_version OR pol.max_attempts<>j.max_attempts THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM reminder_leads WHERE policy_id=pol.id AND minutes=j.lead_minutes)
  AND j.due_at=appt.starts_at-make_interval(mins=>j.lead_minutes) AND j.channel='in_app';
END $function$

CREATE OR REPLACE FUNCTION ramosolo.reminder_source_invalidation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'ramosolo', 'pg_temp'
AS $function$
BEGIN
 IF TG_TABLE_NAME='appointments' THEN
  IF NEW.schedule_version<>OLD.schedule_version OR NEW.status<>OLD.status OR NEW.starts_at<>OLD.starts_at THEN
   PERFORM invalidate_reminder_jobs(NEW.id,NULL,NULL,'appointment_changed'); END IF;
 ELSIF TG_TABLE_NAME='communication_preferences' THEN
  PERFORM invalidate_reminder_jobs(NULL,NEW.id,NULL,'consent_changed');
 ELSIF TG_TABLE_NAME='reminder_policies' THEN
  PERFORM invalidate_reminder_jobs(NULL,NULL,NEW.id,'policy_changed');
 ELSE
  IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.institution_id<>OLD.institution_id THEN
   UPDATE notification_outbox j SET invalidated_at=timezone('UTC',clock_timestamp()),
    state=CASE WHEN j.state='pending' THEN 'cancelled' ELSE j.state END,
    result_code=CASE WHEN j.state='pending' THEN 'recipient_changed' ELSE j.result_code END
   WHERE j.preference_id IN (SELECT id FROM communication_preferences WHERE patient_id=NEW.id) AND j.invalidated_at IS NULL;
  END IF;
 END IF;
 RETURN NEW;
END $function$
